import math

def get_prime_factorization(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_condition(n):
    if n < 2:
        return False

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 == 1 (mod n)
            if (k * k - 1) % n != 0:
                return False
    return True

solutions = []
for n in range(2, 31):
    if check_condition(n):
        factors = get_prime_factorization(n)
        solutions.append((n, factors))

print("Solutions found:")
for n, factors in solutions:
    factor_str = " * ".join([f"{p}^{e}" for p, e in factors.items()])
    print(f"n = {n} (Factorization: {factor_str})")

def lambda_2a(a):
    if a == 1:
        return 1
    elif a == 2:
        return 2
    elif a >= 3:
        return 2**(a - 2)
    else:
        return None

# Test values for a
a_values = [1, 2, 3, 4, 5]
results = {}
for a in a_values:
    lam = lambda_2a(a)
    divides_2 = (lam <= 2)
    results[a] = (lam, divides_2)

for a, (lam, divides_2) in results.items():
    print(f"a={a}, lambda(2^a)={lam}, lambda divides 2? {divides_2}")
